fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let ny = y.len();

    // First matrix: each of the `ny` rows is a clone of `x`
    let x_mat = vec![x.clone(); ny];

    // Second matrix: for each y[i], create a row of length `nx` filled with y[i]
    let y_mat = y.into_iter()
                 .map(|yi| vec![yi; nx])
                 .collect::<Vec<_>>();

    (x_mat, y_mat)
}